===== Project =====
package net.officefloor.hq.app;

/**
 * A project the owner does for a client. Serialised as JSON by the /api/projects routes; carries the
 * client's NAME (joined) so the UI can show it without a second lookup.
 */
public record Project(long id, String name, long clientId, String clientName) {
}
===== ProjectRepository =====
package net.officefloor.hq.app;

import java.util.List;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.jdbc.support.KeyHolder;
import org.springframework.stereotype.Repository;

/** Data access for {@link Project} rows (JdbcTemplate over the schema in V3__projects.sql). */
@Repository
public class ProjectRepository {

    private final JdbcTemplate jdbc;

    public ProjectRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    private static final org.springframework.jdbc.core.RowMapper<Project> MAPPER =
            (rs, i) -> new Project(rs.getLong("id"), rs.getString("name"),
                    rs.getLong("client_id"), rs.getString("client_name"));

    public List<Project> findAll() {
        return jdbc.query(
                "SELECT p.id, p.name, p.client_id, c.name AS client_name"
                        + " FROM projects p JOIN clients c ON p.client_id = c.id"
                        + " ORDER BY p.id",
                MAPPER);
    }

    /** Projects done for one client — reused by the client detail view. */
    public List<Project> findByClient(long clientId) {
        return jdbc.query(
                "SELECT p.id, p.name, p.client_id, c.name AS client_name"
                        + " FROM projects p JOIN clients c ON p.client_id = c.id"
                        + " WHERE p.client_id = ? ORDER BY p.id",
                MAPPER, clientId);
    }

    public Project create(String name, long clientId) {
        KeyHolder keys = new GeneratedKeyHolder();
        jdbc.update(con -> {
            var ps = con.prepareStatement(
                    "INSERT INTO projects (name, client_id) VALUES (?, ?)", new String[] {"id"});
            ps.setString(1, name);
            ps.setLong(2, clientId);
            return ps;
        }, keys);
        String clientName = jdbc.queryForObject(
                "SELECT name FROM clients WHERE id = ?", String.class, clientId);
        return new Project(keys.getKey().longValue(), name, clientId, clientName);
    }

    /** Look up one project (with joined client name), or null when there is no such row. */
    public Project findById(long id) {
        List<Project> rows = jdbc.query(
                "SELECT p.id, p.name, p.client_id, c.name AS client_name"
                        + " FROM projects p JOIN clients c ON p.client_id = c.id"
                        + " WHERE p.id = ?",
                MAPPER, id);
        return rows.isEmpty() ? null : rows.get(0);
    }

    public boolean delete(long id) {
        return jdbc.update("DELETE FROM projects WHERE id = ?", id) > 0;
    }
}
===== ProjectsGetLogic =====
package net.officefloor.hq.app;

import java.util.List;
import net.officefloor.web.HttpQueryParameter;
import net.officefloor.web.ObjectResponse;

/**
 * GET /api/projects — list all projects (each with its client's name). With an optional
 * {@code ?clientId=<id>} it lists only the projects done for that client.
 */
public class ProjectsGetLogic {

    public void service(@HttpQueryParameter("clientId") String clientId,
            ProjectRepository repository, ObjectResponse<List<Project>> response) {
        if (clientId == null || clientId.isBlank()) {
            response.send(repository.findAll());
        } else {
            response.send(repository.findByClient(Long.parseLong(clientId.trim())));
        }
    }
}
===== ProjectsDeletePostLogic =====
package net.officefloor.hq.app;

import net.officefloor.server.http.HttpException;
import net.officefloor.server.http.HttpStatus;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.RequestBody;

/**
 * POST /api/projects/delete — delete a project no longer needed. Removes the row and records one
 * audit line (PROJECT_DELETED id=&lt;id&gt;) so the deletion is kept on record.
 */
public class ProjectsDeletePostLogic {

    public void service(@RequestBody DeleteProject body, ProjectRepository repository, Audit audit,
            ObjectResponse<Project> response) {
        if (body.getId() <= 0) {
            throw new HttpException(HttpStatus.BAD_REQUEST, "A project id is required.");
        }
        Project existing = repository.findById(body.getId());
        if (existing == null) {
            throw new HttpException(HttpStatus.NOT_FOUND, "No such project.");
        }
        repository.delete(existing.id());
        audit.record("PROJECT_DELETED id=" + existing.id());
        response.send(existing);
    }
}
===== ProjectsPostLogic =====
package net.officefloor.hq.app;

import net.officefloor.server.http.HttpException;
import net.officefloor.server.http.HttpStatus;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.RequestBody;

/** POST /api/projects — create a project for a client from the request body. */
public class ProjectsPostLogic {

    public void service(@RequestBody NewProject body, ProjectRepository repository,
            ObjectResponse<Project> response) {
        String name = body.getName() == null ? "" : body.getName().trim();
        if (name.isEmpty()) {
            throw new HttpException(HttpStatus.BAD_REQUEST, "A project name is required.");
        }
        if (body.getClientId() <= 0) {
            throw new HttpException(HttpStatus.BAD_REQUEST, "A client is required.");
        }
        response.send(repository.create(name, body.getClientId()));
    }
}
