                    onClick={() => void onDelete(p.id)}
                  >
                    Delete
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      )}

      {openProjectId !== null ? (
        <>
          <ProjectTasks projectId={openProjectId} />
          <ProjectInvoices projectId={openProjectId} />
        </>
      ) : null}
    </section>
  );
}

